from itertools import chain, combinations

def power_set(iterable):
    s = list(iterable)
    return chain.from_iterable(combinations(s, r) for r in range(len(s)+1))

def has_consecutive(subset):
    sorted_subset = sorted(subset)
    for i in range(len(sorted_subset) - 1):
        if sorted_subset[i+1] == sorted_subset[i] + 1:
            return True
    return False

count = 0
for subset in power_set(range(1, 11)):
    if not has_consecutive(subset):
        if sum(subset) % 2 == 0:
            count += 1
print(count)
